:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a3d;
  --text: #f0f0f5;
  --text-muted: #a0a0b8;
  --accent: #7c6cf0;
  --accent-hover: #9a8cf5;
  --accent-pressed: #5a4ad0;
  --swatch-radius: 12px;
  --focus-ring: 0 0 0 3px rgba(124, 108, 240, 0.6);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
}

.card {
  background: var(--card-bg);
  border-radius: 20px;
  padding: 32px;
  width: 100%;
  max-width: 900px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.4);
}

header {
  text-align: center;
  margin-bottom: 28px;
}

h1 {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.5px;
  margin-bottom: 6px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
  margin-bottom: 28px;
}

.swatch {
  display: flex;
  flex-direction: column;
  border-radius: var(--swatch-radius);
  overflow: hidden;
  background: #1a1a2a;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
  transition: transform 0.15s ease;
}

.swatch:hover {
  transform: translateY(-2px);
}

.swatch-color {
  height: 120px;
  width: 100%;
}

.swatch-info {
  padding: 10px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.hex-code {
  font-family: 'Courier New', monospace;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.5px;
  user-select: all;
}

.lock-btn {
  background: transparent;
  border: 1.5px solid var(--text-muted);
  border-radius: 8px;
  color: var(--text-muted);
  font-size: 0.85rem;
  font-weight: 600;
  padding: 5px 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 4px;
  transition: all 0.15s ease;
  min-height: 32px;
}

.lock-btn:hover {
  border-color: var(--accent-hover);
  color: var(--accent-hover);
}

.lock-btn:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.lock-btn:active {
  transform: scale(0.96);
}

.lock-icon {
  font-size: 0.9rem;
  line-height: 1;
}

.controls {
  display: flex;
  justify-content: center;
}

.btn-generate {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: 12px;
  font-size: 1.05rem;
  font-weight: 600;
  padding: 14px 32px;
  cursor: pointer;
  transition: all 0.15s ease;
  min-height: 48px;
  letter-spacing: 0.3px;
}

.btn-generate:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(124, 108, 240, 0.4);
}

.btn-generate:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

.btn-generate:active {
  background: var(--accent-pressed);
  transform: translateY(0);
  box-shadow: none;
}

@media (max-width: 600px) {
  .palette {
    grid-template-columns: repeat(2, 1fr);
  }
  .swatch:last-child {
    grid-column: span 2;
  }
  .swatch-color {
    height: 90px;
  }
  .card {
    padding: 24px 20px;
  }
  h1 {
    font-size: 1.6rem;
  }
  .btn-generate {
    width: 100%;
    padding: 14px 20px;
  }
}

@media (max-width: 380px) {
  .palette {
    grid-template-columns: 1fr;
  }
  .swatch:last-child {
    grid-column: auto;
  }
  .swatch-color {
    height: 70px;
  }
  .swatch-info {
    flex-direction: row;
    justify-content: space-between;
    padding: 8px 12px;
  }
}

(function () {
  'use strict';

  var SWATCH_COUNT = 5;

  // --- Color utilities ---

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var a = s * Math.min(l, 1 - l);
    var f = function (n) {
      var k = (n + h / 30) % 12;
      var color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return '#' + f(0) + f(8) + f(4);
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  // Generate a harmonious palette using an analogous/triadic base.
  // Returns array of hex strings.
  function generateHarmoniousPalette() {
    var baseHue = randomInt(0, 359);
    // Pick a harmony scheme: 0 = analogous, 1 = triadic, 2 = split-complementary
    var scheme = randomInt(0, 2);
    var hueOffsets;

    if (scheme === 0) {
      // Analogous: hues clustered within ~60 degrees
      hueOffsets = [0, 15, 30, 45, 60];
    } else if (scheme === 1) {
      // Triadic: 120 degree spacing
      hueOffsets = [0, 120, 240, 60, 180];
    } else {
      // Split-complementary
      hueOffsets = [0, 30, 150, 210, 330];
    }

    // Slight shuffle for variety but keep first as base
    var palette = [];
    var baseSat = randomInt(55, 85);
    var baseLight = randomInt(45, 65);

    for (var i = 0; i < SWATCH_COUNT; i++) {
      var h = (baseHue + hueOffsets[i] + randomInt(-8, 8) + 360) % 360;
      var s = Math.min(100, Math.max(30, baseSat + randomInt(-15, 15)));
      var l = Math.min(85, Math.max(20, baseLight + randomInt(-20, 20)));
      palette.push(hslToHex(h, s, l));
    }

    return palette;
  }

  // --- State ---

  var colors = [];       // array of hex strings
  var locked = [];       // array of booleans

  // --- DOM refs ---

  var paletteEl = document.getElementById('palette');
  var generateBtn = document.getElementById('generate');

  // --- Rendering ---

  function render() {
    paletteEl.innerHTML = '';

    for (var i = 0; i < SWATCH_COUNT; i++) {
      var swatch = document.createElement('div');
      swatch.className = 'swatch';

      var colorDiv = document.createElement('div');
      colorDiv.className = 'swatch-color';
      colorDiv.style.backgroundColor = colors[i];
      colorDiv.setAttribute('aria-hidden', 'true');

      var info = document.createElement('div');
      info.className = 'swatch-info';

      var hexSpan = document.createElement('span');
      hexSpan.className = 'hex-code';
      hexSpan.textContent = colors[i].toUpperCase();
      hexSpan.setAttribute('aria-label', 'Color ' + (i + 1) + ': ' + colors[i].toUpperCase());

      var lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.setAttribute('aria-pressed', locked[i] ? 'true' : 'false');
      lockBtn.setAttribute('aria-label', (locked[i] ? 'Unlock' : 'Lock') + ' color ' + (i + 1) + ' ' + colors[i].toUpperCase());
      lockBtn.dataset.index = String(i);

      var icon = document.createElement('span');
      icon.className = 'lock-icon';
      icon.setAttribute('aria-hidden', 'true');
      icon.textContent = locked[i] ? '\uD83D\uDD12' : '\uD83D\uDD13'; // locked/unlocked emoji

      var label = document.createElement('span');
      label.textContent = locked[i] ? 'Locked' : 'Lock';

      lockBtn.appendChild(icon);
      lockBtn.appendChild(label);

      lockBtn.addEventListener('click', onLockToggle);

      info.appendChild(hexSpan);
      info.appendChild(lockBtn);

      swatch.appendChild(colorDiv);
      swatch.appendChild(info);
      paletteEl.appendChild(swatch);
    }
  }

  // --- Event handlers ---

  function onLockToggle(event) {
    var index = parseInt(event.currentTarget.dataset.index, 10);
    locked[index] = !locked[index];
    render();
  }

  function onGenerate() {
    var newPalette = generateHarmoniousPalette();

    for (var i = 0; i < SWATCH_COUNT; i++) {
      if (!locked[i]) {
        colors[i] = newPalette[i];
      }
    }

    render();
  }

  // --- Init ---

  function init() {
    colors = generateHarmoniousPalette();
    locked = [false, false, false, false, false];
    render();
    generateBtn.addEventListener('click', onGenerate);
  }

  init();
})();
